package migracion;
import config.ConexionBD; import java.sql.*; import java.util.*;
public final class MigracionComunidadR33A { private MigracionComunidadR33A(){} public static void main(String[]a){aplicar();}
 public static void aplicar(){try(Connection c=ConexionBD.obtenerConexion()){String db=c.getCatalog();if(db==null||db.isBlank())throw new IllegalStateException("No se pudo identificar la base activa.");crear(c);verificar(c,db);System.out.println("MIGRACION_COMUNIDAD_R33A_OK tablas=5 preferencias="+contar(c,"comunidad_preferencias")+" convocatorias="+contar(c,"comunidad_convocatorias")+" solicitudes="+contar(c,"comunidad_solicitudes")+" participantes="+contar(c,"comunidad_participantes")+" eventos="+contar(c,"comunidad_eventos")+".");}catch(SQLException e){throw new RuntimeException("No se pudo aplicar la migración de Comunidad R3.3A. Revise conectividad y permisos sin publicar credenciales.",e);}}
 private static void crear(Connection c)throws SQLException{
  exec(c,"CREATE TABLE IF NOT EXISTS comunidad_preferencias (cliente_id BIGINT NOT NULL,buscar_turnos TINYINT(1) NOT NULL DEFAULT 0,buscar_torneos TINYINT(1) NOT NULL DEFAULT 0,contacto_whatsapp TINYINT(1) NOT NULL DEFAULT 0,fecha_consentimiento_whatsapp DATETIME NULL,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(cliente_id),CONSTRAINT fk_comunidad_preferencias_cliente FOREIGN KEY(cliente_id) REFERENCES clientes(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  exec(c,"CREATE TABLE IF NOT EXISTS comunidad_convocatorias (id BIGINT NOT NULL AUTO_INCREMENT,reserva_id BIGINT NOT NULL,cliente_creador_id BIGINT NOT NULL,perfil_creador_id BIGINT NOT NULL,categoria_deportiva_id BIGINT NULL,posicion_buscada VARCHAR(20) NULL,participantes_confirmados TINYINT NOT NULL,lugares_buscados TINYINT NOT NULL,estado VARCHAR(35) NOT NULL DEFAULT 'BORRADOR',clave_activa TINYINT NULL,comentario VARCHAR(500) NULL,motivo_cierre VARCHAR(50) NULL,fecha_publicacion DATETIME NULL,fecha_cierre DATETIME NULL,fecha_expiracion DATETIME NOT NULL,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_comunidad_convocatoria_activa(reserva_id,clave_activa),KEY idx_comunidad_convocatorias_publicas(estado,fecha_expiracion,categoria_deportiva_id),KEY idx_comunidad_convocatorias_cliente(cliente_creador_id,fecha_creacion),CONSTRAINT fk_comunidad_convocatoria_reserva FOREIGN KEY(reserva_id) REFERENCES reservas(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_comunidad_convocatoria_cliente FOREIGN KEY(cliente_creador_id) REFERENCES clientes(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_comunidad_convocatoria_perfil FOREIGN KEY(perfil_creador_id) REFERENCES perfiles_jugador(id) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT fk_comunidad_convocatoria_categoria FOREIGN KEY(categoria_deportiva_id) REFERENCES categorias_deportivas(id) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT chk_comunidad_convocatoria_confirmados CHECK(participantes_confirmados BETWEEN 1 AND 3),CONSTRAINT chk_comunidad_convocatoria_lugares CHECK(lugares_buscados BETWEEN 1 AND 3),CONSTRAINT chk_comunidad_convocatoria_total CHECK(participantes_confirmados+lugares_buscados<=4),CONSTRAINT chk_comunidad_convocatoria_clave CHECK((estado IN ('ABIERTA','EN_COORDINACION') AND clave_activa=1) OR (estado NOT IN ('ABIERTA','EN_COORDINACION') AND clave_activa IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  exec(c,"CREATE TABLE IF NOT EXISTS comunidad_participantes (id BIGINT NOT NULL AUTO_INCREMENT,convocatoria_id BIGINT NOT NULL,perfil_jugador_id BIGINT NULL,tipo VARCHAR(20) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'CONFIRMADO',descripcion_publica VARCHAR(120) NULL,origen VARCHAR(25) NOT NULL,fecha_confirmacion DATETIME NULL,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_comunidad_participante_perfil(convocatoria_id,perfil_jugador_id),KEY idx_comunidad_participantes_estado(convocatoria_id,estado),CONSTRAINT fk_comunidad_participante_convocatoria FOREIGN KEY(convocatoria_id) REFERENCES comunidad_convocatorias(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_comunidad_participante_perfil FOREIGN KEY(perfil_jugador_id) REFERENCES perfiles_jugador(id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  exec(c,"CREATE TABLE IF NOT EXISTS comunidad_solicitudes (id BIGINT NOT NULL AUTO_INCREMENT,convocatoria_id BIGINT NOT NULL,perfil_solicitante_id BIGINT NOT NULL,estado VARCHAR(35) NOT NULL DEFAULT 'PENDIENTE',mensaje VARCHAR(300) NULL,fecha_solicitud DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_contacto DATETIME NULL,fecha_resolucion DATETIME NULL,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_comunidad_solicitud_perfil(convocatoria_id,perfil_solicitante_id),KEY idx_comunidad_solicitudes_estado(convocatoria_id,estado,fecha_solicitud),KEY idx_comunidad_solicitudes_perfil(perfil_solicitante_id,fecha_solicitud),CONSTRAINT fk_comunidad_solicitud_convocatoria FOREIGN KEY(convocatoria_id) REFERENCES comunidad_convocatorias(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_comunidad_solicitud_perfil FOREIGN KEY(perfil_solicitante_id) REFERENCES perfiles_jugador(id) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  exec(c,"CREATE TABLE IF NOT EXISTS comunidad_eventos (id BIGINT NOT NULL AUTO_INCREMENT,tipo VARCHAR(60) NOT NULL,convocatoria_id BIGINT NULL,solicitud_id BIGINT NULL,actor_cliente_id BIGINT NULL,actor_perfil_id BIGINT NULL,detalle_json JSON NULL,fecha_evento DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_comunidad_eventos_convocatoria(convocatoria_id,fecha_evento),KEY idx_comunidad_eventos_solicitud(solicitud_id,fecha_evento),KEY idx_comunidad_eventos_tipo(tipo,fecha_evento),CONSTRAINT fk_comunidad_evento_convocatoria FOREIGN KEY(convocatoria_id) REFERENCES comunidad_convocatorias(id) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT fk_comunidad_evento_solicitud FOREIGN KEY(solicitud_id) REFERENCES comunidad_solicitudes(id) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT fk_comunidad_evento_cliente FOREIGN KEY(actor_cliente_id) REFERENCES clientes(id) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT fk_comunidad_evento_perfil FOREIGN KEY(actor_perfil_id) REFERENCES perfiles_jugador(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"); }
 private static void verificar(Connection c,String db)throws SQLException{for(String t:List.of("comunidad_preferencias","comunidad_convocatorias","comunidad_participantes","comunidad_solicitudes","comunidad_eventos"))if(!ex(c,"SELECT 1 FROM information_schema.tables WHERE table_schema=? AND table_name=?",db,t))throw new IllegalStateException("Falta la tabla "+t);if(!ex(c,"SELECT 1 FROM information_schema.statistics WHERE table_schema=? AND table_name='comunidad_convocatorias' AND index_name='uk_comunidad_convocatoria_activa'",db))throw new IllegalStateException("Falta la protección de convocatoria activa única.");}
 private static long contar(Connection c,String t)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM "+t)){r.next();return r.getLong(1);}} private static boolean ex(Connection c,String q,String...v)throws SQLException{try(PreparedStatement s=c.prepareStatement(q)){for(int i=0;i<v.length;i++)s.setString(i+1,v[i]);try(ResultSet r=s.executeQuery()){return r.next();}}} private static void exec(Connection c,String q)throws SQLException{try(Statement s=c.createStatement()){s.execute(q);}}
}